#include <iostream>
#include <string_view>

std::string_view label(int) { return "whole pages"; }
std::string_view label(double) { return "fractional estimate"; }

int main()
{
    std::cout << label(4) << '\n' << label(4.5) << '\n';
    int limit{10};
    const auto allowed = [limit](int pages) { return pages <= limit; };
    limit = 20;
    std::cout << std::boolalpha << allowed(12) << ' ' << allowed(8) << '\n';
    std::cout << "Current limit: " << limit << '\n';
}
